const T2S = {};
for (const [s, t] of Object.entries(S2T)) {
  if (!T2S[t]) T2S[t] = s;
}

export function toTraditional(text) {
  if (!text) return '';
  return text.replace(/[\u4e00-\u9fff]/g, (ch) => S2T[ch] || ch);
}

export function toSimplified(text) {
  if (!text) return '';
  return text.replace(/[\u4e00-\u9fff]/g, (ch) => T2S[ch] || ch);
}

export function convertScript(text, script) {
  if (script === 'traditional') return toTraditional(text);
  return toSimplified(text);
}

export function looksTraditional(text) {
  if (!text) return false;
  const sample = text.slice(0, 1200);
  let hits = 0;
  let total = 0;
  for (const ch of sample) {
    if (ch < '\u4e00' || ch > '\u9fff') continue;
    total += 1;
    if (T2S[ch]) hits += 1;
  }
  return total > 40 && hits / total > 0.08;
}